    markRelayKeySupportConfirmed();
    return true;
  }),
  warnIfRelayLookupUnsupported: vi.fn(async () => ({
    supported: true,
    capabilities: { idempotency: true, version: '1.7.6' },
  })),
}));

vi.mock('@/services/suppressions', () => ({
